# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def _shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [_shift("Ana", 9, 10), _shift("Brisa", 9, 12), _shift("Ana", 13, 15)]
        lines = timesheet_lines(shifts)
        self.assertEqual(lines[0], "Ana: 2 shifts, 3.0 hours")
        self.assertEqual(lines[1], "Brisa: 1 shifts, 3.0 hours")

    def test_more_hours_wins(self):
        shifts = [_shift("Ana", 9, 10), _shift("Brisa", 9, 12)]
        self.assertTrue(timesheet_lines(shifts)[0].startswith("Brisa"))

    def test_one_decimal(self):
        lines = timesheet_lines([Shift("Ana", "tue", Span(540, 620))])
        self.assertEqual(lines, ["Ana: 1 shifts, 1.3 hours"])

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([_shift("  ", 9, 10)])
